"use client"

import * as React from "react"
import gsap from "gsap"

// Full-screen menu that folds the page away. Opening it lifts the page down and
// back into a rounded, tilted sheet while the links rise out of their masks
// above it, one after another. Hovering a link previews its picture on the
// folded sheet, so the page shows where you are about to go.

export type FoldLink = {
  label: string
  href?: string
  /** Shown on the folded page while this link is hovered or focused. */
  image?: string
  /** Small caption beside the number, e.g. "12 projects". */
  note?: string
}

export type FolioFoldMenuProps = {
  links: FoldLink[]
  /** Wordmark in the top bar (string or node). */
  brand?: React.ReactNode
  /** The page itself. It folds away when the menu opens. */
  children?: React.ReactNode
  /** Small row under the links: address, email, socials. */
  footer?: React.ReactNode
  /** Link hover colour and the open button's fill. */
  accent?: string
  /** Stage height. Keep it a definite length; percentages collapse once installed. */
  height?: string
  defaultOpen?: boolean
  className?: string
  onNavigate?: (link: FoldLink, index: number) => void
  onOpenChange?: (open: boolean) => void
}

// #region pose
/** Where the page sits when folded. Reduced motion drops the tilt and the scale. */
export function foldPose(reduced: boolean) {
  return reduced
    ? { yPercent: 56, scale: 1, rotationX: 0, borderRadius: 22 }
    : { yPercent: 56, scale: 0.9, rotationX: 9, borderRadius: 28 }
}

/** Link stagger in seconds: quicker per link as the list grows, capped overall. */
export function linkStagger(n: number): number {
  if (n <= 1) return 0
  return Math.min(0.07, 0.36 / (n - 1))
}

/** Two-digit index label. */
export function pad2(i: number): string {
  return (i < 9 ? "0" : "") + (i + 1)
}
// #endregion

const FONT =
  "@font-face{font-family:ffm-serif;font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}" +
  "@font-face{font-family:ffm-serif;font-style:italic;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}"

const CSS =
  FONT +
  ".ffm-root{position:relative;width:100%;overflow:hidden;isolation:isolate;background:#0d0c0a;color:#f3eee5;perspective:1600px;container-type:inline-size;font-family:ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif}" +
  ".ffm-root::before{content:'';position:absolute;inset:0;z-index:0;background:radial-gradient(120% 80% at 50% -10%,rgba(255,226,186,.13),transparent 60%),radial-gradient(60% 50% at 100% 100%,rgba(140,110,80,.12),transparent 70%)}" +
  ".ffm-root::after{content:'';position:absolute;inset:0;z-index:0;opacity:.22;mix-blend-mode:overlay;pointer-events:none;background-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>\")}" +
  ".ffm-serif{font-family:ffm-serif,'Iowan Old Style','Times New Roman',serif;font-weight:400}" +
  ".ffm-bar{position:absolute;z-index:5;top:0;left:0;right:0;display:flex;align-items:center;justify-content:space-between;padding:22px clamp(18px,3.4cqw,44px);pointer-events:none}" +
  ".ffm-bar>*{pointer-events:auto}" +
  ".ffm-brand{font-size:15px;letter-spacing:.01em;font-weight:600;color:#f6f1e8;text-shadow:0 1px 12px rgba(0,0,0,.25)}" +
  ".ffm-btn{display:inline-flex;align-items:center;gap:12px;height:44px;padding:0 6px 0 18px;border-radius:999px;border:1px solid rgba(255,255,255,.22);background:rgba(20,18,15,.32);backdrop-filter:blur(14px) saturate(140%);-webkit-backdrop-filter:blur(14px) saturate(140%);color:#f6f1e8;font:600 13px/1 ui-sans-serif,system-ui,sans-serif;letter-spacing:.02em;cursor:pointer;box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 10px 30px -12px rgba(0,0,0,.5);transition:background .4s,border-color .4s,transform .25s cubic-bezier(.2,.8,.2,1)}" +
  ".ffm-btn:hover{background:rgba(20,18,15,.5);border-color:rgba(255,255,255,.34)}" +
  ".ffm-btn:active{transform:scale(.96)}" +
  ".ffm-btn:focus-visible{outline:2px solid var(--ffm-accent);outline-offset:3px}" +
  ".ffm-btnlabel{position:relative;display:block;height:14px;overflow:hidden}" +
  ".ffm-btnlabel>span{display:block;height:14px;line-height:14px;transition:transform .6s cubic-bezier(.7,0,.2,1)}" +
  ".ffm-root[data-open] .ffm-btnlabel>span{transform:translateY(-100%)}" +
  ".ffm-burger{position:relative;width:32px;height:32px;border-radius:999px;background:#f6f1e8;transition:background .5s,transform .6s cubic-bezier(.7,0,.2,1)}" +
  ".ffm-root[data-open] .ffm-burger{background:var(--ffm-accent);transform:rotate(180deg)}" +
  ".ffm-burger>i{position:absolute;left:10px;right:10px;height:1.6px;border-radius:2px;background:#15130f;transition:transform .6s cubic-bezier(.7,0,.2,1),top .6s cubic-bezier(.7,0,.2,1)}" +
  ".ffm-burger>i:first-child{top:12.5px}.ffm-burger>i:last-child{top:18px}" +
  ".ffm-root[data-open] .ffm-burger>i:first-child{top:15.2px;transform:rotate(45deg)}" +
  ".ffm-root[data-open] .ffm-burger>i:last-child{top:15.2px;transform:rotate(-45deg)}" +
  ".ffm-menu{position:absolute;z-index:1;left:0;right:0;top:0;height:56%;display:flex;flex-direction:column;justify-content:center;padding:76px clamp(18px,4cqw,56px) 20px}" +
  ".ffm-links{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;justify-content:center;column-gap:clamp(18px,3.4cqw,52px);row-gap:0}" +
  ".ffm-li{position:relative}" +
  ".ffm-link{position:relative;display:flex;align-items:flex-start;gap:8px;color:#f3eee5;text-decoration:none;outline:none;padding:2px 2px}" +
  ".ffm-num{display:block;margin-top:.9em;font:500 11px/1 ui-monospace,'SFMono-Regular',Menlo,monospace;letter-spacing:.06em;color:rgba(243,238,229,.5);transition:color .4s}" +
  ".ffm-mask{display:block;overflow:hidden;font-size:clamp(40px,6.3cqw,104px);padding:.06em .16em .14em .04em;margin-right:-.12em}" +
  ".ffm-roll{position:relative;display:block;line-height:.98;letter-spacing:-.02em;will-change:transform}" +
  ".ffm-face{display:block;transition:transform .7s cubic-bezier(.7,0,.2,1),color .4s}" +
  ".ffm-face+.ffm-face{position:absolute;left:0;top:0;font-style:italic;color:var(--ffm-accent);transform:translateY(105%)}" +
  ".ffm-link:hover .ffm-face:first-child,.ffm-link:focus-visible .ffm-face:first-child{transform:translateY(-105%)}" +
  ".ffm-link:hover .ffm-face+.ffm-face,.ffm-link:focus-visible .ffm-face+.ffm-face{transform:translateY(0)}" +
  ".ffm-link:hover .ffm-num,.ffm-link:focus-visible .ffm-num{color:var(--ffm-accent)}" +
  ".ffm-link:focus-visible{outline:1px dashed rgba(243,238,229,.4);outline-offset:4px;border-radius:6px}" +
  ".ffm-note{position:absolute;left:28px;bottom:-4px;font:500 11px/1 ui-sans-serif,system-ui,sans-serif;letter-spacing:.04em;color:rgba(243,238,229,.46);white-space:nowrap;opacity:0;transform:translateY(6px);transition:opacity .4s,transform .5s cubic-bezier(.2,.8,.2,1)}" +
  ".ffm-link:hover .ffm-note,.ffm-link:focus-visible .ffm-note{opacity:1;transform:none}" +
  ".ffm-foot{display:flex;flex-wrap:wrap;justify-content:center;gap:6px 26px;margin-top:clamp(16px,3cqw,34px);font-size:12px;letter-spacing:.03em;color:rgba(243,238,229,.55)}" +
  ".ffm-foot a{color:inherit;text-decoration:none;transition:color .3s}.ffm-foot a:hover{color:#f3eee5}" +
  ".ffm-page{position:absolute;z-index:2;inset:0;overflow:hidden;transform-origin:50% 0;background:#1a1814;will-change:transform}" +
  ".ffm-root[data-open] .ffm-page{cursor:pointer}" +
  ".ffm-edge{position:absolute;inset:0;z-index:3;pointer-events:none;border-radius:inherit;opacity:0;box-shadow:inset 0 1px 0 rgba(255,255,255,.35),inset 0 0 0 1px rgba(255,255,255,.08)}" +
  ".ffm-shade{position:absolute;inset:0;z-index:2;pointer-events:none;opacity:0;background:linear-gradient(180deg,rgba(13,12,10,.42),rgba(13,12,10,0) 45%)}" +
  ".ffm-prevs{position:absolute;inset:0;z-index:1;pointer-events:none}" +
  ".ffm-prev{position:absolute;inset:0;width:100%;height:100%;max-width:none;object-fit:cover;opacity:0;transform:scale(1.08);transition:opacity .55s ease,transform 1.1s cubic-bezier(.2,.8,.2,1)}" +
  ".ffm-prev[data-on]{opacity:1;transform:scale(1)}" +
  ".ffm-cap{position:absolute;left:clamp(16px,3cqw,36px);top:clamp(16px,2.4cqw,28px);z-index:3;display:flex;align-items:center;gap:10px;padding:8px 14px 8px 8px;border-radius:999px;background:rgba(13,12,10,.5);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);font-size:12px;color:#f3eee5;font:500 12px/1 ui-sans-serif,system-ui,sans-serif;opacity:0;transform:translateY(8px);transition:opacity .4s,transform .5s cubic-bezier(.2,.8,.2,1)}" +
  ".ffm-cap[data-on]{opacity:1;transform:none}" +
  ".ffm-cap>b{display:grid;place-items:center;width:22px;height:22px;border-radius:999px;background:var(--ffm-accent);color:#15130f;font-size:12px}" +
  "@container (max-width:640px){.ffm-links{flex-direction:column;align-items:center}.ffm-mask{font-size:clamp(38px,11.5cqw,64px)}.ffm-note{display:none}.ffm-menu{padding-top:72px}}" +
  "@media (prefers-reduced-motion:reduce){.ffm-face,.ffm-prev,.ffm-cap,.ffm-btnlabel>span,.ffm-burger,.ffm-burger>i,.ffm-note{transition-duration:.01ms}}"

export default function FolioFoldMenu({
  links,
  brand = "Studio",
  children,
  footer,
  accent = "#e8b77a",
  height = "100svh",
  defaultOpen = false,
  className,
  onNavigate,
  onOpenChange,
}: FolioFoldMenuProps) {
  const [open, setOpen] = React.useState(defaultOpen)
  const [hover, setHover] = React.useState(-1)
  const root = React.useRef(null as HTMLDivElement | null)
  const menu = React.useRef(null as HTMLElement | null)
  const btn = React.useRef(null as HTMLButtonElement | null)
  const tl = React.useRef(null as gsap.core.Timeline | null)
  const first = React.useRef(true)
  // Move focus into the menu only when it was opened from the keyboard; a tap would
  // otherwise land focus on the first link and light its preview.
  const byKey = React.useRef(false)
  const id = React.useId()

  const set = React.useCallback(
    (next: boolean) => {
      setOpen(next)
      if (!next) setHover(-1)
      onOpenChange?.(next)
    },
    [onOpenChange]
  )

  // One paused timeline: open plays it, close reverses it from wherever it is.
  React.useEffect(() => {
    const el = root.current
    if (!el) return
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
    const ctx = gsap.context(() => {
      const reduced = mq.matches
      const pose = foldPose(reduced)
      const t = gsap.timeline({ paused: true, defaults: { ease: "expo.inOut" } })
      t.to(".ffm-page", { ...pose, transformPerspective: 1600, duration: reduced ? 0.35 : 1.05 }, 0)
        .to(".ffm-shade, .ffm-edge", { opacity: 1, duration: 0.6, ease: "power2.out" }, 0.3)
        .fromTo(
          ".ffm-roll",
          { yPercent: 118, rotation: reduced ? 0 : 5, transformOrigin: "0% 100%" },
          { yPercent: 0, rotation: 0, duration: reduced ? 0.3 : 1, ease: "expo.out", stagger: linkStagger(links.length) },
          reduced ? 0.05 : 0.38
        )
        .fromTo(".ffm-num", { opacity: 0 }, { opacity: 1, duration: 0.5, ease: "power1.out", stagger: linkStagger(links.length) }, reduced ? 0.1 : 0.6)
        .fromTo(".ffm-foot", { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: 0.6, ease: "power3.out" }, reduced ? 0.1 : 0.82)
      tl.current = t
      if (defaultOpen) t.progress(1)
    }, el)
    return () => {
      ctx.revert()
      tl.current = null
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [links.length])

  React.useEffect(() => {
    const t = tl.current
    menu.current?.toggleAttribute("inert", !open)
    if (first.current) {
      first.current = false
      return
    }
    if (!t) return
    if (open) {
      t.timeScale(1).play()
      if (!byKey.current) return
      const a = menu.current?.querySelector("a")
      window.setTimeout(() => (a as HTMLElement | null)?.focus({ preventScroll: true }), 420)
    } else {
      // Closing runs a touch quicker than opening.
      t.timeScale(1.35).reverse()
    }
  }, [open])

  React.useEffect(() => {
    if (!open) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        set(false)
        btn.current?.focus()
      }
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [open, set])

  const shown = hover > -1 ? links[hover] : undefined

  return (
    <div
      ref={root}
      className={"ffm-root" + (className ? " " + className : "")}
      style={{ height, ["--ffm-accent" as string]: accent }}
      data-open={open ? "" : undefined}
    >
      <style>{CSS}</style>

      <nav ref={menu} id={id} className="ffm-menu" aria-label="Main" aria-hidden={!open}>
        <ul className="ffm-links">
          {links.map((link, i) => (
            <li key={link.label + i} className="ffm-li">
              <a
                className="ffm-link"
                href={link.href ?? "#"}
                onMouseEnter={() => setHover(i)}
                onMouseLeave={() => setHover(-1)}
                onFocus={() => setHover(i)}
                onBlur={() => setHover(-1)}
                onClick={(e) => {
                  if (!link.href) e.preventDefault()
                  onNavigate?.(link, i)
                }}
              >
                <span className="ffm-num" aria-hidden="true">
                  {pad2(i)}
                </span>
                <span className="ffm-mask">
                  <span className="ffm-roll ffm-serif">
                    <span className="ffm-face">{link.label}</span>
                    <span className="ffm-face" aria-hidden="true">
                      {link.label}
                    </span>
                  </span>
                </span>
                {link.note ? <span className="ffm-note">{link.note}</span> : null}
              </a>
            </li>
          ))}
        </ul>
        {footer ? <div className="ffm-foot">{footer}</div> : null}
      </nav>

      <div className="ffm-page" onClick={open ? () => set(false) : undefined} aria-hidden={open || undefined}>
        {children}
        <div className="ffm-prevs">
          {links.map((link, i) =>
            link.image ? (
              <img key={i} className="ffm-prev" src={link.image} alt="" draggable={false} data-on={hover === i ? "" : undefined} />
            ) : null
          )}
        </div>
        <div className="ffm-shade" />
        <div className="ffm-cap" data-on={shown?.image ? "" : undefined}>
          <b aria-hidden="true">↗</b>
          {shown?.label}
        </div>
        <div className="ffm-edge" />
      </div>

      <header className="ffm-bar">
        <div className="ffm-brand">{brand}</div>
        <button
          ref={btn}
          type="button"
          className="ffm-btn"
          aria-expanded={open}
          aria-controls={id}
          onClick={(e) => {
            byKey.current = e.detail === 0
            set(!open)
          }}
        >
          <span className="ffm-btnlabel">
            <span>Menu</span>
            <span aria-hidden="true">Close</span>
          </span>
          <span className="ffm-burger" aria-hidden="true">
            <i />
            <i />
          </span>
        </button>
      </header>
    </div>
  )
}
